import{z as i,x as l,o,c as p,q as r,j as t,D as a,d as A,s as E,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Qwen3 解码器：GQA、RoPE、QK-Norm","description":"","frontmatter":{"title":"Qwen3 解码器：GQA、RoPE、QK-Norm","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-asr-decoder.md","filePath":"llm/qwen3-asr-decoder.md","lastUpdated":1791413859000}'),Q={name:"llm/qwen3-asr-decoder.md"};function m(h,e,d,B,R,c){const n=l("Mermaid");return o(),p("div",null,[e[2]||(e[2]=r('<h1 id="qwen3-解码器-gqa、rope、qk-norm" tabindex="-1">Qwen3 解码器：GQA、RoPE、QK-Norm <a class="header-anchor" href="#qwen3-解码器-gqa、rope、qk-norm" aria-label="Permalink to &quot;Qwen3 解码器：GQA、RoPE、QK-Norm&quot;">​</a></h1><div class="epigraph"><p>Qwen3-ASR-1.7B 以 Qwen3-1.7B 为解码器，Qwen3-ASR-0.6B 以 Qwen3-0.6B 为解码器；二者都经 projector 读取 AuT。</p><footer>—— Qwen Team, Qwen3-ASR Technical Report, arXiv:2601.21337</footer></div><p>识别的最后一公里不是再做一个 AED 解码器，而是<strong>沿用 Qwen3 的因果语言模型</strong>：Grouped-Query Attention、RoPE、QK-Norm。音频前缀进残差流之后，生成转写的规则与生成文本相同——只是系统被 SFT 成 ASR-only 槽位。本篇写这三件解码器构件如何服务语音前缀：GQA 压 KV、RoPE 给音频与文字同一套相对几何、QK-Norm 稳住长前缀上的分数尺度。对照 Whisper 的交叉注意力解码器，以及 Ainslie 的 GQA、Su 的 RoPE 与 Qwen3 / 稳定训练文献中的 QK-Norm。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LALM 的解码器要同时满足三件事。其一，音频前缀可长达二十分钟量级的 12.5 Hz 向量，KV 缓存按层、按头、按长度涨，服务并发会被带宽打死。其二，前缀是声学、后缀是文字，两种 token 要在同一套位置几何里做点积，不能音频用正弦、文字用 RoPE。其三，前缀长度从流式 1 秒跳到离线数分钟，softmax 的尺度若随长度漂，首 token 就抖。Whisper 用专门的编码器–解码器与交叉注意力，三项分别用较短的 30 秒块、解码器自注意力、训练时的固定形状来回避。Qwen3-ASR 选择不另开解码器家族，于是必须把 Qwen3 已有的 GQA、RoPE、QK-Norm 用对。</p><h3 id="解码器是语言模型-不是第二套-aut" tabindex="-1">解码器是语言模型，不是第二套 AuT <a class="header-anchor" href="#解码器是语言模型-不是第二套-aut" aria-label="Permalink to &quot;解码器是语言模型，不是第二套 AuT&quot;">​</a></h3><p>AuT 自己在预训练时是 AED，含编码器自注意力与解码器交叉注意力。进入 Qwen3-ASR 之后，发布图的右支是：预训练 AuT 编码器 → projector → Qwen3 LM。文字侧不再走 AuT 的解码器。因此本篇的 GQA / RoPE / QK-Norm 指 <strong>Qwen3 主干</strong>，不是 AuT 内部层。混写会把编码器窗和语言模型 KV 算进同一笔账。</p><p><span class="marginnote">0.6B 与 1.7B 的差别主要在 Qwen3 深度与宽度，以及配套 AuT 的 180M / 896 对 300M / 1024。GQA、RoPE、QK-Norm 是同一套结构选择，不是大号才有、小号没有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="gqa-查询头分组共享-kv" tabindex="-1">GQA：查询头分组共享 KV <a class="header-anchor" href="#gqa-查询头分组共享-kv" aria-label="Permalink to &quot;GQA：查询头分组共享 KV&quot;">​</a></h3><p>Ainslie 等人的 Grouped-Query Attention 让 \\(h_q\\) 个查询头共享 \\(h_{kv}\\) 组键值，\\(g=h_q/h_{kv}\\)。解码时 KV 字节与 \\(h_{kv}\\) 成正比，与 \\(h_q\\) 无关。音频前缀很长时，这一点比纯文本对话更关键：前缀每秒新增 12.5 个键，会议和歌曲会把缓存拉成「文本对话的许多倍」。GQA 把斜率打下去，才能在 vLLM 批处理里用 0.6B 换到高并发、约 92 ms 级 TTFT。训练与推理必须同一分组，不能预训练 MHA、上线改 GQA。</p><p><span class="marginnote">数字实例：20 分钟音频约 15000 个音频 token，按 28 层、8 个 KV 组、每头 128 维、BF16 每数 2 字节算，单条请求的键值缓存约 1.6 GB——一条长音频就吃掉一张卡的一角，这就是 GQA 要把 KV 组数压下来的服务学动机。</span></p><h3 id="rope-音频下标与文字下标同一旋转" tabindex="-1">RoPE：音频下标与文字下标同一旋转 <a class="header-anchor" href="#rope-音频下标与文字下标同一旋转" aria-label="Permalink to &quot;RoPE：音频下标与文字下标同一旋转&quot;">​</a></h3><p>Su 等人的 RoPE 在 Q、K 上按位置旋转，内积只含相对位移。音频前缀占用 \\(0\\ldots N-1\\)，文字从 \\(N\\) 起。相对几何保证「当前字去看半秒前的声学 token」是合法的 \\(n-m\\)，无需为音频另学一张位置表。流式短窗下 \\(N\\) 小，离线长音频 \\(N\\) 大，旋转公式不变；会变的是未见过的大距离上的数值，那是频率外推问题，不是 ASR 特有的新编码。</p><p><span class="marginnote">直觉类比：RoPE 给每个位置发一根按角度偏转的指针，两个 token 做点积时比的是两根指针的夹角——夹角只取决于「隔多远」，不取决于「从第几个数起」。所以把音频向量排在前面，文字照样能按相对距离去「看」它们。</span></p><h3 id="qk-norm-先归一化再打分" tabindex="-1">QK-Norm：先归一化再打分 <a class="header-anchor" href="#qk-norm-先归一化再打分" aria-label="Permalink to &quot;QK-Norm：先归一化再打分&quot;">​</a></h3><p>Qwen3 及部分稳定训练文献在注意力里对 \\(Q\\)、\\(K\\) 做逐头（或逐向量）RMSNorm，再缩放点积：</p> \\[\\mathrm{head}=\\mathrm{softmax}\\left(\\frac{\\mathrm{RMS}(Q)\\,\\mathrm{RMS}(K)^\\top}{\\sqrt{d_k}}\\right)V. \\]<p>长音频前缀使某些头的 \\(Q\\)、\\(K\\) 范数随层放大，没有 QK-Norm 时 logits 进入饱和，后面的文字 token 几乎只看最近几个位置。有了逐查询、逐键的归一化，尺度被钉住，GQA 的共享键也不会因为某一头范数爆炸而独占分组。这是「能把分钟级前缀喂进小解码器」的数值条件。</p>',19)),(o(),t(s,null,{default:a(()=>[E(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E9%9F%B3%E9%A2%91%E5%89%8D%E7%BC%80%E5%8A%A0%E6%96%87%E5%AD%97%22%5D%20--%3E%20QKN%5B%22QK-Norm%22%5D%0A%20%20QKN%20--%3E%20ROPE%5B%22RoPE%20%E6%97%8B%E8%BD%AC%20Q%20%E4%B8%8E%20K%22%5D%0A%20%20ROPE%20--%3E%20GQA%5B%22GQA%20%E5%88%86%E7%BB%84%E7%82%B9%E7%A7%AF%22%5D%0A%20%20GQA%20--%3E%20OUT%5B%22%E7%94%9F%E6%88%90%20language%20%E4%B8%8E%20asr_text%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[A(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<p><span class="marginnote">顺序上 RoPE 与 QK-Norm 的先后以 Qwen3 实现为准：先投影，再对 Q/K 归一化，再旋转，再 GQA 打分。评测复现时不要把 Norm 加在旋转之后又再转一次，那会破坏 \\(R_m^\\top R_n=R_{n-m}\\) 与单位范数的组合假设。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GQA 在识别里的机制是：<strong>声学记忆按组共享，字面路由仍多头</strong>。同一组查询头去读同一段 12.5 Hz 前缀，适合「这段音频在说什么」这类全局问题；组间仍可分化出噪声抑制、语种、专名等通道。这比 MQA 全部挤一头更不容易把方言和歌声挤丢，又比 MHA 便宜。RoPE 则让「看前缀的哪一格」成为相对距离问题：当前正在写的汉字，倾向对齐最近几百毫秒的声学 token，这与 80 ms 格子相洽。</p><h3 id="与-whisper-交叉注意力的分工" tabindex="-1">与 Whisper 交叉注意力的分工 <a class="header-anchor" href="#与-whisper-交叉注意力的分工" aria-label="Permalink to &quot;与 Whisper 交叉注意力的分工&quot;">​</a></h3><p>Whisper 解码器每层用交叉注意力去编码器记忆里检索，自注意力只在已生成文字上。Qwen3-ASR 把检索折叠进自注意力：音频向量已经作为前缀键值躺在缓存里，文字查询直接点它们。GQA 作用于这整段混合序列。效果是实现简单、与文本服务同栈；代价是无法在深层再学一套专门的「听」头——「听」必须已经在 projector 输出里。QK-Norm 在这种混合序列上尤其有用：音频向量和文本嵌入的原始范数往往不同，归一化后才在同一 softmax 里竞争。</p><p>SFT 把输出限制为语种槽加转写，解码器的语言建模能力被收窄到 ASR。GQA/RoPE/QK-Norm 并不因此消失；它们仍然决定前缀能有多长、多稳。RL（GSPO）再在难例上调策略，改的是生成分布，不是这三件结构。结构是能服务的前提，后训练是槽位与鲁棒性。</p><p>Whisper 与 Qwen3-ASR 读取音频的方式可以并排看：一个是每层发查询去编码器记忆里检索，一个是把音频键值常驻缓存、文字查询在自注意力里一次点到。这张图回答的是「音频到底在哪一步被读到」：</p>',7)),(o(),t(s,null,{default:a(()=>[E(n,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20WH%5B%22Whisper%20%E5%BC%8F%22%5D%0A%20%20%20%20T1%5B%22%E5%B7%B2%E7%94%9F%E6%88%90%E7%9A%84%E6%96%87%E5%AD%97%22%5D%20--%3E%20CA%5B%22%E6%AF%8F%E5%B1%82%E5%8F%91%E5%87%BA%E4%BA%A4%E5%8F%89%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20%20%20CA%20--%3E%20ENC%5B%22%E5%8E%BB%E7%BC%96%E7%A0%81%E5%99%A8%E8%AE%B0%E5%BF%86%E9%87%8C%E6%A3%80%E7%B4%A2%22%5D%0A%20%20%20%20ENC%20--%3E%20T1%0A%20%20end%0A%20%20subgraph%20QW%5B%22Qwen3-ASR%20%E5%BC%8F%22%5D%0A%20%20%20%20PRE%5B%22%E9%9F%B3%E9%A2%91%E5%89%8D%E7%BC%80%20KV%20%E5%B8%B8%E9%A9%BB%E7%BC%93%E5%AD%98%22%5D%20---%20TXT%5B%22%E6%96%87%E5%AD%97%20token%20%E6%8B%BC%E5%9C%A8%E5%85%B6%E5%90%8E%22%5D%0A%20%20%20%20TXT%20--%3E%20SA%5B%22%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%9B%B4%E6%8E%A5%E7%82%B9%E5%88%B0%E9%9F%B3%E9%A2%91%E9%94%AE%22%5D%0A%20%20end%0A%20%20WH%20-.-%3E%7C%22%E6%A3%80%E7%B4%A2%E6%8A%98%E5%8F%A0%E8%BF%9B%E5%89%8D%E7%BC%80%22%7C%20QW%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[A(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>GQA 不能在组内保存两套冲突的声学记忆。若某一层必须同时精细保留两个说话人，而 \\(h_{kv}\\) 很小，应靠前端窗切开说话人，或接受混叠。RoPE 不提供绝对时间：它不知道「这是第 3 分钟」，只知道相对。产品要展示时钟，必须用 ForcedAligner 的 80 ms 索引，不能从 RoPE 相位反解。QK-Norm 会削弱用范数编码的置信度；若有人想从注意力范数读「模型有多确定」，在 Qwen3 解码器上会误读。</p><p><span class="marginnote">不要把编码器动态窗和 GQA 当成同一类稀疏。窗是对音频键的硬裁切；GQA 是对头的共享。流式短窗已经把 \\(n\\) 裁小，GQA 的收益主要在离线长前缀与高并发。短句上两者的差别会缩小，不能用 3 秒测试片断否定 GQA。</span></p><p>另一边界：ASR-only 不等于可以删掉语言模型容量。专名、歌词、代码切换依赖 Qwen3 的世界知识；GQA 只减 KV，不减 FFN。0.6B 的效率优势来自更浅更窄的 Qwen3 加更小的 AuT，不是来自「识别不需要 LM」。把解码器换成随机初始化的小 Transformer、只保留 GQA 外壳，会丢掉报告里相对 Whisper 与商业 API 的那截质量。</p><p><span class="marginnote">常见误区：初学者容易以为音频进 LLM 前要「先翻译成文字」——实际上 projector 输出的是一组连续向量，直接当作普通 token 参与注意力和前馈运算，LLM 对它做的计算与文字 token 完全相同，只是这些向量的内容由声音决定。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发布模型的解码器就是 Qwen3：GQA 减 KV，RoPE 统一音文相对位置，QK-Norm 稳住长前缀打分。</li><li>音频以 projector 前缀进入自注意力，不再使用 Whisper 式逐层交叉注意力。</li><li>GQA 的收益随 12.5 Hz 前缀变长而显现，服务侧与 vLLM 批处理绑定。</li><li>绝对时间戳不在 RoPE 里，而在 ForcedAligner 的 80 ms 格子上。</li><li>结构三件套不能替代后训练的 ASR 槽位约束，也不能单独解释 0.6B / 1.7B 的质量差。</li><li>出处：Qwen Team, <em>Qwen3-ASR Technical Report</em>, arXiv:2601.21337；Ainslie 等，GQA，2023；Su 等，RoPE / RoFormer；QK-Norm 见 Qwen3 与相关稳定训练文献；对照 Radford 等，Whisper，2022。</li></ul>',7))])}const P=i(Q,[["render",m]]);export{_ as __pageData,P as default};
